using Microsoft.EntityFrameworkCore;using FreshCycle.Api.Models;namespace FreshCycle.Api.Data;public class AppDbContext:DbContext{public AppDbContext(DbContextOptions<AppDbContext>o):base(o){}public DbSet<ServiceItem>Services=>Set<ServiceItem>();public DbSet<Order>Orders=>Set<Order>();}public static class DbSeeder{public static void Seed(AppDbContext d){if(!d.Services.Any()){d.Services.AddRange(new ServiceItem{Name="Wash & Fold",Description="Everyday clothing, washed and folded.",Price=12},new ServiceItem{Name="Dry Cleaning",Description="Professional care for delicate garments.",Price=18},new ServiceItem{Name="Ironing",Description="Crisp, ready-to-wear laundry.",Price=8});d.SaveChanges();}}}